mapper.select:
SELECT * FROM utb_invoice_mst
WHERE invoice_seq = #{invoiceSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'N'

SELECT /* [1. Invoice 마스터 기본 정보] */ mst.office_seq AS officeSeq, mst.invoice_seq AS invoiceSeq, mst.app_seq AS appSeq, mst.customer_seq AS customerSeq, mst.biz_info_seq AS bizInfoSeq, mst.invoice_no AS invNo, mst.invoice_category_code AS invCategoryCode, fn_get_cd_nm('BILL_DIV_CD', mst.invoice_category_code) AS invCategoryName, mst.invoice_type_code AS invTypeCode, fn_get_cd_nm('BILL_TYPE_CD', mst.invoice_type_code) AS invTypeName, mst.invoice_class_code AS invClassCode, fn_get_cd_nm('BILL_EVENT_DIV', mst.invoice_class_code) AS invClassName, mst.client_ref AS clientRef,
mst.debit_no AS debitNo, mst.oa_document_code AS oaDocument, mst.invoice_content AS invContent, mst.agent_invoice_category_code AS agentInvCategoryCode, fn_get_cd_nm('AGENT_TYPE', mst.agent_invoice_category_code) AS agentInvCategoryName, mst.currency_unit AS currencyUnitCode, fn_get_cd_nm('CURRENCY_TYPE', mst.currency_unit) AS currencyUnitName, mst.exchange_rate AS exchangeRate, mst.give_up_content AS abandonContent, mst.outsource_content AS outsourceContent, mst.tax_bill_no AS taxBillNo, mst.tax_bill_category_code AS taxBillCategoryCode, fn_get_cd_nm('TAX_STMT_DIV', mst.tax_bill_category_code) AS taxBillCategoryName, mst.tax_bill_type_code AS taxBillTypeCode, fn_get_cd_nm('TAXBILL_TYPE', mst.tax_bill_type_code) AS taxBillTypeName, mst.note AS note,
/* [2. Invoice 관련 날짜 정보 - to_char 적용] */ to_char(due."invDate", 'YYYYMMDD') AS invDate, to_char(due."invSendDate", 'YYYYMMDD') AS invSendDate, to_char(due."taxBillDate", 'YYYYMMDD') AS taxBillDate, to_char(due."abandonDate", 'YYYYMMDD') AS abandonDate, to_char(due."govFeePayDate", 'YYYYMMDD') AS govFeePayDate, to_char(due."agentInvDate", 'YYYYMMDD') AS agentInvDate, to_char(due."debitReceiptDate", 'YYYYMMDD') AS debitReceiptDate, to_char(due."exchangeRateDate", 'YYYYMMDD') AS exchangeRateDate, to_char(due."vatPayDate", 'YYYYMMDD') AS vatPayDate, to_char(due."outsourceDate", 'YYYYMMDD') AS outsourceDate, to_char(due."perfDate", 'YYYYMMDD') AS perfDate,
/* [3. Invoice 관련 사람 정보] */ pp."invMgr" AS invMgr, pp."invMgr_NM" AS invMgrName, -- pp."adminMgr" AS adminMgr, -- pp."adminMgr_NM" AS adminMgrName, -- pp."caseMgr" AS caseMgr, -- pp."caseMgr_NM" AS caseMgrName, pp."attorney" AS attorney, pp."attorney_NM" AS attorneyName, pp."customerContact" AS customerContact, pp."customerContact_NM" AS customerContactName, COALESCE(mst."foreign_agent", pp."foreignAgent_NM", pp_app."foreignAgent_NM") AS foreignAgentName,
pp_app."applicant" AS applicant, pp_app."applicant_NM" AS applicantName,
COALESCE(pp."client", mst."client", pp_app."client") AS client, COALESCE(mst."client", pp."client_NM", pp_app."client_NM") AS clientName,
/* [4. Invoice 관련 비용 정보] */ fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'govFee') AS govFee, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'agencyFee') AS agencyFee, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'vat') AS vat, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'etcFee') AS etcFee, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'totalInvAmount') AS totalInvAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'unpaidAmount') AS unpaidAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'depAmount') AS depAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'govFeePayAmount') AS govFeePayAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'perfAmount') AS perfAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'abandonAmount') AS abandonAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'transFee') AS transFee, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'remitForeignFee') AS remitForeignFee, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'remitKrwFee') AS remitKrwFee, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'outsourceCost') AS outsourceCost, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'outsourceVat') AS outsourceVat, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'exchangeDiffAmount') AS exchangeDiffAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'krwAmount') AS krwAmount, fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'foreignCostAmount') AS foreignCostAmount,
/* [5. 출원(App) 마스터 정보 및 뷰 조인 정보] */ app.app_no AS appNo, app.app_name_ko AS titleKo, app.app_name_en AS titleEn, app.right_category AS rightTypeCode, fn_get_cd_nm('PAT_TYPE', app.right_category) AS rightTypeName, app.country_code AS countryCode, fn_get_ctry_nm(app.country_code, 'C', 'KO') AS countryName, app.asset_no AS ourRef, app.agent_ref AS yourRef, COALESCE(mst.case_classification, app.app_classification) AS caseCategoryCode, COALESCE(fn_get_cd_nm('CASE_CLASSIFICATION', mst.case_classification), fn_get_cd_nm('NAT_IO_DIV', app.app_classification)) AS caseCategoryName, app.app_route AS caseCategory, app.reg_no AS regNo, app.grade AS grade, app.independent_claim AS independentClaims, app.dependent_claim AS dependentClaims, app.drawing_paper_count AS drawingCount, app.figure_count AS figureCount, app.spec_page AS specCount, app.oversea_spec_page AS overseaSpecCount, app.product_class AS niceClass, app.dept_code AS deptName, /* 출원 기준 날짜 정보 (due_app 뷰) */ to_char(due_app."appDate", 'YYYYMMDD') AS appDate, to_char(due_app."regDate", 'YYYYMMDD') AS regDate,
/* 출원 기준 사람 정보 (pp_app 뷰) */ pp_app."adminMgr" AS adminMgr, pp_app."adminMgr_NM" AS adminMgrName, pp_app."caseMgr" AS caseMgr, pp_app."caseMgr_NM" AS caseMgrName, /* [6. 기타 조인 상세 (고객/사업자)] */ cust.client_name_ko AS customerName, biz.biz_corp_name AS bizName, biz.ceo_name AS bizCeo, biz.biz_reg_no AS bizRegNo, biz.biz_type AS bizType, biz.biz_kind AS bizItem, biz.biz_workplace_no AS bizWorkplaceNo, biz.biz_addr AS bizAddr, biz.biz_dept_name AS bizDeptName, biz.biz_contact_name AS bizContactName, biz.biz_email AS bizEmail
FROM utb_invoice_mst mst /* 청구서 전용 피벗 조인 */ LEFT JOIN v_total_duedate_pivot due ON mst.invoice_seq = due.tbl_seq AND mst.office_seq = due.office_seq LEFT JOIN v_participant_pivot pp ON mst.invoice_seq = pp.tbl_seq AND mst.office_seq = pp.office_seq /* 출원 마스터 및 출원 전용 피벗 조인 */ LEFT JOIN utb_app_mst app ON mst.office_seq = app.office_seq AND mst.app_seq = app.app_seq LEFT JOIN v_total_duedate_pivot due_app ON app.app_seq = due_app.tbl_seq AND app.office_seq = due_app.office_seq LEFT JOIN v_participant_pivot pp_app ON app.app_seq = pp_app.tbl_seq AND app.office_seq = pp_app.office_seq /* 고객/사업자 조인 */ LEFT JOIN utb_customer cust ON mst.office_seq = cust.office_seq AND mst.customer_seq = cust.customer_seq LEFT JOIN utb_biz_info biz ON mst.office_seq = biz.office_seq AND mst.biz_info_seq = biz.biz_info_seq
WHERE mst.office_seq = #{officeSeq} AND mst.invoice_seq = #{invoiceSeq} AND mst.del_yn = 'N' ORDER BY mst.create_at, mst.update_at DESC LIMIT 1;

/* [검색 및 표시 필드 전체 복구] */ SELECT * FROM ( SELECT mst.office_seq AS "officeSeq", mst.invoice_seq AS "invoiceSeq", mst.app_seq AS "appSeq", mst.customer_seq AS "customerSeq", mst.biz_info_seq AS "bizInfoSeq", mst.invoice_no AS "invNo", mst.invoice_category_code AS "invCategoryCode", "MP_IPMS_PA".fn_get_cd_nm('BILL_DIV_CD', mst.invoice_category_code) AS "invCategoryName", mst.invoice_type_code AS "invTypeCode", "MP_IPMS_PA".fn_get_cd_nm('BILL_TYPE_CD', mst.invoice_type_code) AS "invTypeName", mst.invoice_class_code AS "invClassCode", "MP_IPMS_PA".fn_get_cd_nm('BILL_EVENT_DIV', mst.invoice_class_code) AS "invClassName", mst.client_ref AS "clientRef", mst.debit_no AS "debitNo", mst.oa_document_code AS "oaDocument", mst.invoice_content AS "invContent", mst.agent_invoice_category_code AS "agentInvCategoryCode", "MP_IPMS_PA".fn_get_cd_nm('AGENT_TYPE', mst.agent_invoice_category_code) AS "agentInvCategoryName", mst.currency_unit AS "currencyUnitCode", "MP_IPMS_PA".fn_get_cd_nm('CURRENCY_TYPE', mst.currency_unit) AS "currencyUnitName", mst.exchange_rate AS "exchangeRate", mst.give_up_content AS "abandonContent", mst.outsource_content AS "outsourceContent", mst.tax_bill_no AS "taxBillNo", CASE WHEN mst.tax_bill_no IS NOT NULL THEN 'Y' ELSE 'N' END AS "taxBillYn", mst.case_classification AS "caseClassification", mst.tax_bill_category_code AS "taxBillCategoryCode", "MP_IPMS_PA".fn_get_cd_nm('TAX_STMT_DIV', mst.tax_bill_category_code) AS "taxBillCategoryName", mst.tax_bill_type_code AS "taxBillTypeCode", "MP_IPMS_PA".fn_get_cd_nm('TAXBILL_TYPE', mst.tax_bill_type_code) AS "taxBillTypeName", mst.note AS "note",
/* 날짜 필드 복구 */ to_char(due."invDate", 'YYYYMMDD') AS "invDate", to_char(due."invSendDate", 'YYYYMMDD') AS "invSendDate", to_char(due."taxBillDate", 'YYYYMMDD') AS "taxBillDate", to_char(due."abandonDate", 'YYYYMMDD') AS "abandonDate", to_char(due."govFeePayDate", 'YYYYMMDD') AS "govFeePayDate", to_char(due."agentInvDate", 'YYYYMMDD') AS "agentInvDate", to_char(due."debitReceiptDate", 'YYYYMMDD') AS "debitReceiptDate", to_char(due."exchangeRateDate", 'YYYYMMDD') AS "exchangeRateDate", to_char(due."vatPayDate", 'YYYYMMDD') AS "vatPayDate", to_char(due."outsourceDate", 'YYYYMMDD') AS "outsourceDate", to_char(due."perfDate", 'YYYYMMDD') AS "perfDate",
/* 사람 필드 복구 */ pp."invMgr" AS "invMgr", pp."invMgr_NM" AS "invMgrName", pp."attorney_NM" AS "attorneyNm", pp."customerContact" AS "customerContact", pp."customerContact_NM" AS "customerContactName", perf.staff_name AS "perfMgrName", perf.dept_name AS "perfDeptName",
/* 비용 필드 전체 복구 */ "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'govFee') AS "govFee", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'agencyFee') AS "agencyFee", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'vat') AS "vat", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'etcFee') AS "etcFee", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'totalInvAmount') AS "totalInvAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'unpaidAmount') AS "unpaidAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'depAmount') AS "depAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'govFeePayAmount') AS "govFeePayAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'perfAmount') AS "perfAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'abandonAmount') AS "abandonAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'transFee') AS "transFee", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'remitForeignFee') AS "remitForeignFee", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'remitKrwFee') AS "remitKrwFee", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'outsourceCost') AS "outsourceCost", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'outsourceVat') AS "outsourceVat", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'exchangeDiffAmount') AS "exchangeDiffAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'krwAmount') AS "krwAmount", "MP_IPMS_PA".fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'foreignCostAmount') AS "foreignCostAmount",
/* 출원 및 기타 정보 복구 */ app.app_no AS "appNo", app.app_name_ko AS "titleKo", app.app_name_en AS "titleEn", app.right_category AS "rightTypeCode", "MP_IPMS_PA".fn_get_cd_nm('PAT_TYPE', app.right_category) AS "rightTypeName", app.country_code AS "countryCode", "MP_IPMS_PA".fn_get_ctry_nm(app.country_code, 'C', 'KO') AS "countryName", app.asset_no AS "ourRef", app.agent_ref AS "yourRef", COALESCE(mst.case_classification, app.app_classification) AS "caseCategoryCode", COALESCE("MP_IPMS_PA".fn_get_cd_nm('CASE_CLASSIFICATION', mst.case_classification), "MP_IPMS_PA".fn_get_cd_nm('NAT_IO_DIV', app.app_classification)) AS "caseCategoryName", app.reg_no AS "regNo", app.dept_code AS "deptName", to_char(due_app."appDate", 'YYYYMMDD') AS "appDate", to_char(due_app."regDate", 'YYYYMMDD') AS "regDate",
COALESCE(pp."applicant_NM", pp_app."applicant_NM") AS "applicantNm", COALESCE(pp."client", mst."client", pp_app."client") AS "client", COALESCE(mst."client", pp."client_NM", pp_app."client_NM") AS "clientNm", COALESCE(pp."foreignAgent", mst."foreign_agent", pp_app."foreignAgent") AS "foreignAgent", COALESCE(mst."foreign_agent", pp."foreignAgent_NM", pp_app."foreignAgent_NM") AS "foreignAgentName", pp_app."adminMgr_NM" AS "adminMgrNm", pp_app."caseMgr_NM" AS "caseMgrNm",
cust.client_name_ko AS "customerName", biz.biz_corp_name AS "bizName", (SELECT to_char(MAX(deposit_send_date), 'YYYYMMDD') FROM "MP_IPMS_PA".utb_invoice_banking WHERE invoice_seq = mst.invoice_seq AND office_seq = mst.office_seq) AS "depositDate", mst.create_at AS "createAt"
FROM "MP_IPMS_PA".utb_invoice_mst mst LEFT JOIN "MP_IPMS_PA".utb_app_mst app ON mst.office_seq = app.office_seq AND mst.app_seq = app.app_seq LEFT JOIN "MP_IPMS_PA".v_total_duedate_pivot due ON mst.invoice_seq = due.tbl_seq AND mst.office_seq = due.office_seq LEFT JOIN "MP_IPMS_PA".v_participant_pivot pp ON mst.invoice_seq = pp.tbl_seq AND mst.office_seq = pp.office_seq LEFT JOIN "MP_IPMS_PA".v_total_duedate_pivot due_app ON app.app_seq = due_app.tbl_seq AND app.office_seq = due_app.office_seq LEFT JOIN "MP_IPMS_PA".v_participant_pivot pp_app ON app.app_seq = pp_app.tbl_seq AND app.office_seq = pp_app.office_seq LEFT JOIN "MP_IPMS_PA".utb_customer cust ON mst.office_seq = cust.office_seq AND mst.customer_seq = cust.customer_seq LEFT JOIN "MP_IPMS_PA".utb_biz_info biz ON mst.office_seq = biz.office_seq AND mst.biz_info_seq = biz.biz_info_seq LEFT JOIN ( SELECT p.invoice_seq, p.office_seq, u.user_name_ko AS staff_name, fn_get_cd_nm('DEPT_TYPE', p.dept_category_code) AS dept_name FROM "MP_IPMS_PA".utb_performance p LEFT JOIN "MP_IPMS_PA".utb_user_info u ON p.staff = u.user_info_seq WHERE p.del_yn = 'N' ORDER BY p.share_ratio DESC LIMIT 1 ) perf ON mst.invoice_seq = perf.invoice_seq AND mst.office_seq = perf.office_seq
WHERE mst.office_seq = #{request.officeSeq} AND mst.in_out_type = #{inOutType} AND mst.del_yn = 'N' ) AS T WHERE 1=1
ORDER BY T."createAt" DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}

SELECT /* [1. 기본 정보 및 시퀀스] */ mst.invoice_seq AS "invoiceSeq", mst.office_seq AS "officeSeq", mst.app_seq AS "appSeq", mst.invoice_no AS "invNo", mst.invoice_content AS "invContent",
/* [2. 코드 정보 및 명칭] */ mst.invoice_category_code AS "invCategoryCode", fn_get_cd_nm('BILL_DIV_CD', mst.invoice_category_code) AS "invCategoryName", COALESCE(mst.case_classification, app.app_classification) AS "caseCategoryCode", COALESCE(fn_get_cd_nm('CASE_CLASSIFICATION', mst.case_classification), fn_get_cd_nm('NAT_IO_DIV', app.app_classification)) AS "caseCategoryName",
/* [3. 날짜 정보 - Pivot 뷰 활용] */ to_char(due."invDate", 'YYYYMMDD') AS "invDate", to_char(due."taxBillDate", 'YYYYMMDD') AS "taxBillDate", (SELECT to_char(MAX(deposit_send_date), 'YYYYMMDD') FROM utb_invoice_banking WHERE invoice_seq = mst.invoice_seq AND office_seq = mst.office_seq) AS "depositDate",
/* [4. 비용 정보 - 함수 활용] */ fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'govFee') AS "govFee", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'agencyFee') AS "agencyFee", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'vat') AS "vat", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'transFee') AS "transFee", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'etcFee') AS "etcFee", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'totalInvAmount') AS "totalInvAmount", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'depAmount') AS "depAmount", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'unpaidAmount') AS "unpaidAmount", fn_get_cost_amount(mst.office_seq, mst.invoice_seq, 'abandonAmount') AS "abandonAmount"
FROM utb_invoice_mst mst /* 출원 마스터 조인 (사건구분 및 기본정보 추출) */ INNER JOIN utb_app_mst app ON mst.office_seq = app.office_seq AND mst.app_seq = app.app_seq /* 날짜 피벗 뷰 조인 */ LEFT JOIN v_total_duedate_pivot due ON mst.invoice_seq = due.tbl_seq AND mst.office_seq = due.office_seq
WHERE mst.office_seq = #{request.officeSeq} AND mst.app_seq = #{request.tblSeq} /* 특정 사건번호 필터링 */ AND mst.del_yn = 'N' /* del_yn 아님 주의: 주신 쿼리 기준 del_yn */ ORDER BY mst.create_at DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}

SELECT COUNT(*)
FROM utb_invoice_mst
WHERE office_seq = #{request.officeSeq}
  AND app_seq = #{request.tblSeq}
  AND del_yn
          = 'N'

mapper.update:
UPDATE utb_invoice_claim
SET del_yn = 'Y', update_at = CURRENT_TIMESTAMP
WHERE invoice_seq = #{invoiceSeq} AND office_seq = #{officeSeq}

mapper.select:
SELECT b.banking_seq, b.invoice_seq, b.office_seq, b.banking_category, fn_get_cd_nm('BANKING_TYPE', b.banking_category) AS bankingCategoryName, -- 카테고리 명칭 추가 b.banking_kind, b.deposit_send_date, b.deposit_check_date, b.deposit_amount, b.deposit_name, b.deposit_bank, b.currency_unit, fn_get_cd_nm('CURRENCY_TYPE', b.currency_unit) AS currencyUnitName, -- 통화 명칭 추가 b.exchange_ratio, b.exchange_amount, b.deposit_fee, b.deposit_way, fn_get_cd_nm('PAY_METHOD_CD', b.deposit_way) AS depositWayName, -- 송금방식 명칭 추가 b.note, b.prepayment_deposit_no, b.general_prepayment_balance, b.general_prepayment_used_amount, b.designated_prepayment_balance, b.designated_prepayment_used_amount, b.create_user, b.create_at, b.update_user, b.update_at FROM "MP_IPMS_PA".utb_invoice_banking b WHERE b.invoice_seq = #{request.tblSeq} AND b.office_seq = #{request.officeSeq} AND b.del_yn = 'N'
AND b.banking_category = #{bankingCategory}
AND b.banking_kind = #{bankingKind}
AND (b.banking_kind IS NULL OR b.banking_kind != '해외대리인송금')
ORDER BY b.deposit_send_date DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}

mapper.update:
UPDATE "MP_IPMS_PA".utb_invoice_banking
SET del_yn = 'Y', update_at = CURRENT_TIMESTAMP
WHERE invoice_seq = #{invoiceSeq} AND office_seq = #{officeSeq}

UPDATE utb_performance SET /* 실적 정보 수정 */ staff = #{staff}, performance_category_code = #{performanceCategoryCode}, dept_category_code = #{deptCategory}, performance_content = #{performanceContent}, performance_perf_date = NULLIF(#{performancePerfDate}, '')::timestamptz,
/* 금액 및 비율 수정 */ performance_amount = #{performanceAmount}, share_ratio = #{shareRatio}, note = #{note},
/* 공통 로그 정보 */ update_user = #{updateUser}, update_at = CURRENT_TIMESTAMP, del_yn = 'N' WHERE performance_seq = #{performanceSeq} AND office_seq = #{officeSeq}

UPDATE utb_performance
SET del_yn = 'Y', update_at = CURRENT_TIMESTAMP
WHERE invoice_seq = #{invoiceSeq} AND office_seq = #{officeSeq}

mapper.select:
SELECT /* [1. 출원 마스터 및 분쟁 정보] */ am.app_seq AS appSeq, am.app_no AS appNo, am.app_name_ko AS titleKo, am.app_name_en AS titleEn, am.asset_no AS ourRef, am.agent_ref AS yourRef, am.reg_no AS regNo, am.product_class AS niceClass, am.domestic_reg_no AS domesticRegNo, am.grade AS grade, am.dept_code AS deptName, --fn_get_cd_nm('', am.dept_code) AS deptName, am.retain_seq AS clientRef, cm.conflict_seq AS conflictSeq,
/* [2. 코드/국가 정보] */ am.right_category AS rightTypeCode, fn_get_cd_nm('PAT_TYPE', am.right_category) AS rightTypeName, am.app_classification AS caseCategoryCode, fn_get_cd_nm('CASE_CLASSIFICATION', am.app_classification) AS caseCategoryName, am.country_code AS countryCode, fn_get_ctry_nm(am.country_code, 'C', 'KO') AS countryName,
/* [3. 규격 정보] */ am.independent_claim AS independentClaims, am.dependent_claim AS dependentClaims, am.drawing_paper_count AS drawingCount, am.figure_count AS figureCount, am.spec_page AS specCount,
/* [4. 날짜/사람 정보 (피벗 뷰 조인)] */ to_char(due."appDate", 'YYYYMMDD') AS appDate, to_char(due."regDate", 'YYYYMMDD') AS regDate, to_char(due."regDecisionDate", 'YYYYMMDD') AS domesticRegDecisionDate, to_char(due."domesticRegDate", 'YYYYMMDD') AS domesticRegDate, to_char(due."pubDate", 'YYYYMMDD') AS pubDate, to_char(due."intlPubDate", 'YYYYMMDD') AS intlRegDate, pp."applicant" AS applicant, pp."applicant_NM" AS applicantNm, pp."client" AS client, pp."client_NM" AS clientNm, pp."foreignAgent" AS agent, pp."foreignAgent_NM" AS agentName, pp."adminMgr" AS adminMgr, pp."adminMgr_NM" AS adminMgrNm, pp."caseMgr" AS caseMgr, pp."caseMgr_NM" AS caseMgrNm, pp."attorney" AS attorney, pp."attorney_NM" AS attorneyNm
FROM utb_app_mst am LEFT JOIN utb_conflict_mst cm ON am.app_seq = cm.app_seq AND cm.del_yn = 'N' LEFT JOIN v_total_duedate_pivot due ON am.app_seq = due.tbl_seq AND am.office_seq = due.office_seq LEFT JOIN v_participant_pivot pp ON am.app_seq = pp.tbl_seq AND am.office_seq = pp.office_seq
WHERE am.office_seq = #{request.officeSeq} AND am.del_yn = 'N'
/* [5. 검색 조건: 리스트 내부 필드 접근] */
AND ( am.app_no ILIKE CONCAT('%', #{cond.codeValue}, '%') OR am.asset_no ILIKE CONCAT('%', #{cond.codeValue}, '%') OR cm.asset_no ILIKE CONCAT('%', #{cond.codeValue}, '%') )
AND am.app_name_ko ILIKE CONCAT('%', #{cond.codeValue}, '%')
/* [6. 정렬 및 페이징] */ ORDER BY am.create_at DESC, am.app_seq DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}
